  t = t.replace(/\b(?:[Dd]iam?|DIAM?)\.(?=[ \t]*(?:[A-Z(]|\n|$)|[ \t]+(?:determine|...|take|what|which|how|is|...|express)[ \t]+\S)/g, 'diameter.');
  t = t.replace(/\b(?:[Dd]iam?|DIAM?)\b\.?(?![A-Za-z0-9])/g, 'diameter');
